[
  {
    "statement": "The evidence for using acoustic devices to reduce human-wildlife conflict differs between aquaculture systems and fishing gear applications.",
    "citations": []
  },
  {
    "statement": "For aquaculture systems, studies on acoustic devices have shown mixed results.",
    "citations": []
  },
  {
    "statement": "Some studies found that acoustic devices reduced predation on caged salmon by seals and sea lions.",
    "citations": []
  },
  {
    "statement": "Some studies found that acoustic devices reduced seal approaches to fish cages.",
    "citations": []
  },
  {
    "statement": "Two studies found no reduction in seal predation around fin-fish farms.",
    "citations": []
  },
  {
    "statement": "Two studies found no reduction in dolphin presence around fin-fish farms.",
    "citations": []
  },
  {
    "statement": "For fishing gear applications, the evidence for the effectiveness of acoustic devices is more limited and less promising.",
    "citations": []
  },
  {
    "statement": "One study found that increasing the distance between an acoustic decoy and fishing lines reduced sperm whale presence at the lines.",
    "citations": []
  },
  {
    "statement": "The same study found that the acoustic decoys did not affect whale arrival times or the whales' overall presence.",
    "citations": []
  },
  {
    "statement": "Studies on acoustic devices deployed from fishing vessels showed that dolphins avoided the boats more frequently.",
    "citations": []
  },
  {
    "statement": "Studies on acoustic devices deployed from fishing vessels showed that killer whales maintained greater distances during initial exposure.",
    "citations": []
  },
  {
    "statement": "The acoustic devices deployed from fishing vessels did not reduce the predation of squid catches by dolphins.",
    "citations": []
  },
  {
    "statement": "Acoustic devices appear to show more consistent beneficial effects for reducing human-wildlife conflict at aquaculture systems compared to the use of acoustic devices on fishing gear.",
    "citations": []
  },
  {
    "statement": "The effects of acoustic devices are either limited or ineffective for reducing catch predation when used on fishing gear.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence shows that acoustically reflective fishing gear materials have more consistent positive results compared to attached acoustically reflective objects.",
    "citations": []
  },
  {
    "statement": "Five studies on acoustically reflective materials showed mixed but more encouraging results.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Three controlled studies found reduced entanglements of harbour porpoises in nets made from iron-oxide or barium sulfate materials.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Two studies found acoustically reflective materials had no effect on dolphin entanglements.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Behavior studies showed some reduction in echolocation clicks by harbour porpoises at barium sulfate nets.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "The approach distances of harbour porpoises to barium sulfate nets remained similar to conventional nets.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Attached acoustically reflective objects showed consistently negative results across two studies.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "One controlled study found that metallic bead chains attached to fishing nets did not reduce dolphin entanglements.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "Another controlled study found that acrylic beads attached next to fishing hooks did not reduce sperm whale predation on fish catches.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "The evidence base for acoustically reflective materials is notably different from the evidence base for attached acoustically reflective objects.",
    "citations": []
  },
  {
    "statement": "Acoustically reflective materials were tested in five studies across multiple regions, including Canada, Denmark, and Argentina.",
    "citations": [
      "2807"
    ]
  },
  {
    "statement": "Attached acoustically reflective objects were only tested in two studies, in Australia and Alaska.",
    "citations": [
      "2806"
    ]
  },
  {
    "statement": "More research support exists for investigating acoustically reflective materials as a potential mitigation strategy.",
    "citations": []
  }
]

